"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timedelta(0),
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_INT = re.compile(r"[0-9]+\Z")


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        raise _bad(f"bad size {v!r}")
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _dur(v):
    if v == "off":
        return None
    m = _DUR.match(v)
    if not m:
        raise _bad(f"bad duration {v!r}")
    n = int(m.group(1))
    return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: n})


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = _OFF.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _bad(f"bad offset {v!r}")
    d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -d if m.group(1) == "-" else d


def _int(minimum, allow_off=False):
    def f(v):
        if allow_off and v == "off":
            return None
        if not _INT.match(v) or int(v) < minimum:
            raise _bad(f"bad number {v!r}")
        return int(v)

    return f


PARSERS = {
    "max_size": _size,
    "max_age": _dur,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _int(0),
    "keep": _int(1),
    "keep_days": _int(1, True),
}


class Policy:
    def __init__(self, defaults, sections):
        self.defaults = defaults
        self.sections = sections  # name -> dict

    def names(self):
        return set(self.sections)

    def get(self, name):
        s = dict(BUILTIN)
        s.update(self.defaults)
        s.update(self.sections.get(name, {}))
        return s


def load(path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults = None
    sections = {}
    cur = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise _bad(f"bad line {line!r}")
            head = line[1:-1]
            if head == "defaults":
                if defaults is not None:
                    raise _bad("duplicate section")
                defaults = cur = {}
            elif head.startswith("stream ") and streams.valid(head[7:]):
                n = head[7:]
                if n in sections:
                    raise _bad("duplicate section")
                sections[n] = cur = {}
            else:
                raise _bad(f"unknown section {head!r}")
            continue
        if cur is None or "=" not in line:
            raise _bad(f"bad line {line!r}")
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip()
        if k not in PARSERS:
            raise _bad(f"unknown key {k!r}")
        if k in cur:
            raise _bad(f"duplicate key {k!r}")
        cur[k] = PARSERS[k](v)
    return Policy(defaults or {}, sections)
