"""The rotate command (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, state, streams
from logkeep.errors import DataError, Refused

_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_NUM = r"[1-9][0-9]*"
_K = r"[2-9]|[1-9][0-9]+"
_DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.(" + _K + r"))?\Z")


def parse_time(v):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(v, str):
        return None
    try:
        if _LEGACY.match(v):
            return datetime.strptime(v, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        t = datetime.fromisoformat(v)
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def _whole(v):
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0


def check_state(doc, existing):
    for name in sorted(existing):
        e = doc["streams"].get(name)
        if e is None:
            continue
        if "opened" in e and parse_time(e["opened"]) is None:
            raise DataError("state", f"{name}: bad opened")
        if "rotations" in e and not _whole(e["rotations"]):
            raise DataError("state", f"{name}: bad rotations")
        if "archives" in e:
            a = e["archives"]
            if not isinstance(a, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for k, v in a.items():
                if parse_time(v) is None:
                    raise DataError("state", f"{name}: bad archive time {k}")


class Arc:
    def __init__(self, old, key, gz, k=None, day=None, new=False):
        self.old = old  # file name before the run (None for new: set later)
        self.key = key
        self.gz = gz
        self.day = day
        self.k = k
        self.new = new


def find_archives(logs, name, naming):
    out = []
    seen = {}
    if not logs.is_dir():
        return out
    prefix = name + ".log."
    for p in sorted(logs.iterdir(), key=lambda p: p.name):
        n = p.name
        if not n.startswith(prefix) or not p.is_file():
            continue
        rest = n[len(prefix):]
        gz = rest.endswith(".gz")
        if gz:
            rest = rest[:-3]
        if naming == "numbered":
            if not re.fullmatch(_NUM, rest):
                continue
            key = (int(rest),)
            a = Arc(n, key, gz)
        else:
            m = _DAY.match(rest)
            if not m:
                continue
            try:
                d = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            k = int(m.group(2)) if m.group(2) else 1
            key = (d, k)
            a = Arc(n, key, gz, k=k, day=d)
        if key in seen:
            raise DataError("archives", f"{name}: two archives in the same place")
        seen[key] = a
        out.append(a)
    return out


def _order(arcs, naming):
    # newest first
    if naming == "numbered":
        return sorted(arcs, key=lambda a: a.key)
    return sorted(arcs, key=lambda a: a.key, reverse=True)


def _first_line_time(path):
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    tok = text.split(" ", 1)[0]
    t = parse_time(tok) if not _LEGACY.match(tok) else None
    return t


def run(ctx, names, dry_run, force):
    now = ctx.now
    pol = policy.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(ctx.data)) | pol.names()
    check_state(doc, existing)
    if names:
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        todo = sorted(set(names))
    else:
        todo = sorted(existing)
    logs = streams.logs_dir(ctx.data)

    plans = []
    for name in todo:
        s = pol.get(name)
        naming = s["naming"]
        arcs = find_archives(logs, name, naming)
        plans.append((name, s, arcs))

    lines = []
    tot_r = tot_x = tot_c = 0
    writes = []  # (path, bytes) to write after deletions
    deletes = []
    new_entries = {}
    stamp = dates.stamp(now)

    for name, s, arcs in plans:
        naming = s["naming"]
        log = streams.log_path(ctx.data, name)
        entry = doc["streams"].get(name, {})
        # decision
        if not log.is_file():
            why = None
            label = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                why, label = None, "empty"
            elif force:
                why, label = "forced", "rotate (forced)"
            elif s["max_size"] is not None and size >= s["max_size"]:
                why, label = "size", "rotate (size)"
            else:
                why, label = None, "not due"
                if s["max_age"] is not None:
                    if "opened" in entry:
                        op = parse_time(entry["opened"])
                    else:
                        op = _first_line_time(log)
                    if op is not None and now - op >= s["max_age"]:
                        why, label = "age", "rotate (age)"
        rotated = why is not None
        times = {}
        for k, v in (entry.get("archives") or {}).items():
            times[k] = parse_time(v)
        raw_times = entry.get("archives") or {}

        if rotated:
            if naming == "numbered":
                newarc = Arc(None, (0,), False, new=True)
            else:
                off = timezone(s["offset"])
                day = now.astimezone(off).date()
                ks = [a.k for a in arcs if a.day == day]
                k = max(ks) + 1 if ks else 1
                newarc = Arc(None, (day, k), False, k=k, day=day, new=True)
            arcs = arcs + [newarc]
        ordered = _order(arcs, naming)

        removed = []
        kept = []
        for i, a in enumerate(ordered, 1):
            drop = i > s["keep"]
            if not drop and s["keep_days"] is not None and not a.new:
                t = times.get(a.old)
                if t is not None and now - t >= timedelta(days=s["keep_days"]):
                    drop = True
            (removed if drop else kept).append(a)

        # final names
        arc_state = {}
        out_lines = []
        compressed = 0
        base = name + ".log."
        for i, a in enumerate(kept, 1):
            comp = a.gz or i > s["compress_after"]
            if comp and not a.gz:
                compressed += 1
            if naming == "numbered":
                final = f"{base}{i}" + (".gz" if comp else "")
            else:
                final = base + a.day.isoformat() + (f".{a.k}" if a.k > 1 else "") + (".gz" if comp else "")
            a.final = final
            a.comp = comp
            if a.new:
                out_lines.append(f"  new {final}")
                arc_state[final] = stamp
            else:
                out_lines.append(f"  {final} <- {a.old}" if final != a.old else f"  {final}")
                if a.old in raw_times:
                    arc_state[final] = raw_times[a.old]
        for a in removed:
            if a.new:
                if naming == "numbered":
                    nm = f"{base}{ordered.index(a) + 1}"
                else:
                    nm = base + a.day.isoformat() + (f".{a.k}" if a.k > 1 else "")
                out_lines.append(f"remove {nm}")
            else:
                out_lines.append(f"remove {a.old}")
        # removal lines must come after the kept ones; reorder
        keep_lines = [l for l in out_lines if not l.startswith("remove ")]
        rem_lines = [l for l in out_lines if l.startswith("remove ")]
        lines.append(f"{name}: {label}")
        lines.extend(keep_lines)
        lines.extend(rem_lines)
        tot_r += rotated
        tot_x += len(removed)
        tot_c += compressed

        ne = {}
        if rotated:
            ne["opened"] = stamp
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = (entry.get("rotations") or 0) + (1 if rotated else 0)
        ne["archives"] = arc_state
        new_entries[name] = ne

        if dry_run:
            continue
        # file operations
        active_bytes = None
        if rotated:
            active_bytes = log.read_bytes()
        for a in removed:
            if not a.new:
                deletes.append(logs / a.old)
        for a in kept:
            if a.new:
                data = active_bytes
                if a.comp:
                    data = gzip.compress(data, mtime=0)
                writes.append((logs / a.final, data))
            elif a.final != a.old:
                data = (logs / a.old).read_bytes()
                if a.comp and not a.gz:
                    data = gzip.compress(data, mtime=0)
                deletes.append(logs / a.old)
                writes.append((logs / a.final, data))
        if rotated:
            writes.append((log, b""))

    lines.append(f"{tot_r} rotated, {tot_x} removed, {tot_c} compressed")
    if dry_run:
        lines.append("dry run: nothing written")
        return lines
    for p in deletes:
        p.unlink()
    for p, data in writes:
        p.write_bytes(data)
    doc["streams"].update(new_entries)
    state.save(ctx.state_path, doc)
    return lines
